1349	// Returns in seconds how long to wait before trying to start the VM again.
1350	func calculateStartBackoffTime(failCount int, maxDelay int) int {
1351		// The algorithm is designed to work well with a dynamic maxDelay
1352		// if we decide to expose this as a tuning in the future.
1353		minInterval := 10
1354		delaySeconds := 0
1355	
1356		if failCount <= 0 {
1357			failCount = 1
1358		}
1359	
1360		multiplier := int(math.Pow(float64(failCount), float64(2)))
1361		interval := maxDelay / 30
1362	
1363		if interval < minInterval {
1364			interval = minInterval
1365		}
1366	
1367		delaySeconds = interval * multiplier
1368		randomRange := (delaySeconds / 2) + 1
1369		// add randomized seconds to offset multiple failing VMs from one another
1370		delaySeconds += rand.Intn(randomRange)
1371	
1372		if delaySeconds > maxDelay {
1373			delaySeconds = maxDelay
1374		}
1375	
1376		return delaySeconds
1377	}
